begin;
create type public.audit_action as enum('INSERT','UPDATE','DELETE');
create table public.audit_logs(id bigint generated always as identity primary key,entity_type text not null,entity_id text not null,action public.audit_action not null,changed_fields text[] not null default '{}',actor_id uuid references public.profiles(id) on delete set null,occurred_at timestamptz not null default now(),constraint audit_entity_type_not_blank check(length(trim(entity_type))>0),constraint audit_entity_id_not_blank check(length(trim(entity_id))>0));
create index idx_audit_logs_occurred_at on public.audit_logs(occurred_at desc);create index idx_audit_logs_entity on public.audit_logs(entity_type,entity_id,occurred_at desc);create index idx_audit_logs_actor on public.audit_logs(actor_id,occurred_at desc);
create function public.write_audit_log()returns trigger language plpgsql security definer set search_path=public as $$declare old_data jsonb;new_data jsonb;fields text[];row_id text;begin if tg_op='DELETE' then row_id=old.id::text;fields='{}';else row_id=new.id::text;new_data=to_jsonb(new)-array['created_at','updated_at','created_by','updated_by'];if tg_op='INSERT' then select coalesce(array_agg(k.key order by k.key),'{}') into fields from jsonb_object_keys(new_data) as k(key);else old_data=to_jsonb(old)-array['created_at','updated_at','created_by','updated_by'];select coalesce(array_agg(n.key order by n.key),'{}') into fields from jsonb_each(new_data)n where n.value is distinct from old_data->n.key;if cardinality(fields)=0 then return new;end if;end if;end if;insert into public.audit_logs(entity_type,entity_id,action,changed_fields,actor_id)values(tg_table_name,row_id,tg_op::public.audit_action,fields,auth.uid());if tg_op='DELETE' then return old;end if;return new;end;$$;revoke all on function public.write_audit_log() from public;
create trigger audit_projects after insert or update or delete on public.projects for each row execute procedure public.write_audit_log();create trigger audit_workstreams after insert or update or delete on public.workstreams for each row execute procedure public.write_audit_log();create trigger audit_interns after insert or update or delete on public.interns for each row execute procedure public.write_audit_log();create trigger audit_tasks after insert or update or delete on public.tasks for each row execute procedure public.write_audit_log();create trigger audit_programs after insert or update or delete on public.programs for each row execute procedure public.write_audit_log();create trigger audit_resources after insert or update or delete on public.resources for each row execute procedure public.write_audit_log();create trigger audit_deliverables after insert or update or delete on public.deliverables for each row execute procedure public.write_audit_log();create trigger audit_decisions after insert or update or delete on public.decisions for each row execute procedure public.write_audit_log();create trigger audit_manager_notes after insert or update or delete on public.manager_notes for each row execute procedure public.write_audit_log();create trigger audit_intern_reviews after insert or update or delete on public.intern_reviews for each row execute procedure public.write_audit_log();create trigger audit_kpi_definitions after insert or update or delete on public.kpi_definitions for each row execute procedure public.write_audit_log();create trigger audit_kpi_results after insert or update or delete on public.kpi_results for each row execute procedure public.write_audit_log();

create function public.admin_delete_entity(p_entity_type text,p_entity_id uuid)returns void language plpgsql security definer set search_path=public as $$begin
 if not public.is_admin() then raise exception '삭제 권한이 없습니다.';end if;
 case p_entity_type
 when 'task' then update public.tasks set parent_task_id=null where parent_task_id=p_entity_id;delete from public.task_updates where task_id=p_entity_id;delete from public.task_assignees where task_id=p_entity_id;update public.resources set task_id=null where task_id=p_entity_id;update public.deliverables set task_id=null where task_id=p_entity_id;update public.decisions set task_id=null where task_id=p_entity_id;update public.manager_notes set task_id=null where task_id=p_entity_id;delete from public.tasks where id=p_entity_id;
 when 'workstream' then update public.tasks set parent_task_id=null where workstream_id=p_entity_id;delete from public.task_updates where task_id in(select id from public.tasks where workstream_id=p_entity_id);delete from public.task_assignees where task_id in(select id from public.tasks where workstream_id=p_entity_id);update public.resources set task_id=null where task_id in(select id from public.tasks where workstream_id=p_entity_id);update public.deliverables set task_id=null where task_id in(select id from public.tasks where workstream_id=p_entity_id);update public.decisions set task_id=null where task_id in(select id from public.tasks where workstream_id=p_entity_id);update public.manager_notes set task_id=null where task_id in(select id from public.tasks where workstream_id=p_entity_id);delete from public.tasks where workstream_id=p_entity_id;delete from public.workstreams where id=p_entity_id;
 when 'project' then delete from public.deliverable_reviews where deliverable_version_id in(select v.id from public.deliverable_versions v join public.deliverables d on d.id=v.deliverable_id where d.project_id=p_entity_id);delete from public.deliverable_versions where deliverable_id in(select id from public.deliverables where project_id=p_entity_id);delete from public.deliverables where project_id=p_entity_id;delete from public.resources where project_id=p_entity_id;update public.decisions set supersedes_decision_id=null where project_id=p_entity_id;delete from public.decisions where project_id=p_entity_id;delete from public.manager_notes where project_id=p_entity_id;delete from public.intern_reviews where project_id=p_entity_id;delete from public.kpi_results where kpi_definition_id in(select id from public.kpi_definitions where project_id=p_entity_id);delete from public.kpi_definitions where project_id=p_entity_id;delete from public.program_projects where project_id=p_entity_id;delete from public.project_members where project_id=p_entity_id;update public.tasks set parent_task_id=null where project_id=p_entity_id;delete from public.task_updates where task_id in(select id from public.tasks where project_id=p_entity_id);delete from public.task_assignees where task_id in(select id from public.tasks where project_id=p_entity_id);delete from public.tasks where project_id=p_entity_id;delete from public.workstreams where project_id=p_entity_id;delete from public.projects where id=p_entity_id;
 when 'intern' then delete from public.task_assignees where intern_id=p_entity_id;delete from public.program_enrollments where intern_id=p_entity_id;delete from public.project_members where intern_id=p_entity_id;delete from public.manager_notes where intern_id=p_entity_id;delete from public.intern_reviews where intern_id=p_entity_id;delete from public.kpi_results where kpi_definition_id in(select id from public.kpi_definitions where intern_id=p_entity_id);delete from public.kpi_definitions where intern_id=p_entity_id;delete from public.interns where id=p_entity_id;
 when 'program' then delete from public.program_enrollments where program_id=p_entity_id;delete from public.program_projects where program_id=p_entity_id;delete from public.intern_reviews where program_id=p_entity_id;delete from public.kpi_results where kpi_definition_id in(select id from public.kpi_definitions where program_id=p_entity_id);delete from public.kpi_definitions where program_id=p_entity_id;delete from public.programs where id=p_entity_id;
 when 'resource' then delete from public.resources where id=p_entity_id;
 when 'deliverable' then delete from public.deliverable_reviews where deliverable_version_id in(select id from public.deliverable_versions where deliverable_id=p_entity_id);delete from public.deliverable_versions where deliverable_id=p_entity_id;delete from public.deliverables where id=p_entity_id;
 when 'decision' then update public.decisions set supersedes_decision_id=null where supersedes_decision_id=p_entity_id;delete from public.decisions where id=p_entity_id;
 when 'manager_note' then delete from public.manager_notes where id=p_entity_id;
 when 'intern_review' then delete from public.intern_reviews where id=p_entity_id;
 when 'kpi_definition' then delete from public.kpi_results where kpi_definition_id=p_entity_id;delete from public.kpi_definitions where id=p_entity_id;
 when 'kpi_result' then delete from public.kpi_results where id=p_entity_id;
 else raise exception '지원하지 않는 삭제 대상입니다.';end case;
 if not found then raise exception '삭제할 대상을 찾을 수 없습니다.';end if;
end;$$;revoke all on function public.admin_delete_entity(text,uuid) from public;grant execute on function public.admin_delete_entity(text,uuid) to authenticated;
grant select on public.audit_logs to authenticated;alter table public.audit_logs enable row level security;create policy audit_logs_admin_select on public.audit_logs for select to authenticated using((select public.is_admin()));commit;
